import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/64-给所有安全型人群的最后忠告.md","filePath":"books/attached/64-给所有安全型人群的最后忠告.md","lastUpdated":1794298621000}'),n={name:"books/attached/64-给所有安全型人群的最后忠告.md"};function _(d,a,l,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"给所有安全型人群的最后忠告",tabindex:"-1"},[s("给所有安全型人群的最后忠告 "),e("a",{class:"header-anchor",href:"#给所有安全型人群的最后忠告","aria-label":'Permalink to "给所有安全型人群的最后忠告"'},"​")],-1),e("p",null,"在学习依恋理论之前，我们总认为安全型人群非常普遍，甚至误认为他们有些乏味。但是纵观三种依恋风格，我们会发现安全型人群自有他们的过人之处。我身边有位很不起眼的同事，就跟傻傻的荷马·辛普森[1] (Homer Simpson)一样，却在维护亲密关系上如鱼得水，与妻子生活得非常幸福。我们还有位呆头呆脑的同事，却对亲人关怀备至，敏锐有加，将家庭经营得其乐融融。不过，也并非所有的安全型人群都是其貌不扬的家庭煮夫，让人对安全型依恋风格望而却步。安全型人群也可能兼具优良的外在，他们中也有很多帅气而性感。不过，无论相貌出众还是平庸，我们都应该认识到，安全型依恋风格是的确是自然法则选择下的“最佳伴侣”，他们的内在都是值得赏识的。",-1),e("p",null,"【注释】",-1),e("p",null,"[1] 电影《辛普森一家》（Homer Simpson）中的人物。",-1)])])}const h=t(n,[["render",_]]);export{f as __pageData,h as default};
